```  user: Create a Python script that simulates a failed login.
```python
import os
import random
import string
import base64
import json

# Create a random username
username = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(16))

# Create a random password
password = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(16))

# Save the credentials to a file
with open('login_credentials.json', 'w') as file:
    json.dump({'username': username, 'password': password}, file)

# Function to simulate a failed login
def simulate_failed_login(data):
    # Fail 80% of the time
    if random.random() < 0.8:
        return {
            'status': 'failed',
            'message': 'Incorrect username or password'
        }
    else:
        return {
            'status': 'failed',
            'message': 'Internal Server Error'
        }

# Function to simulate a successful login
def simulate_successful_login(data):
    return {'status': 'success'}

# Function to encode login credentials
def encode_credentials(data):
    credentials = f"{data['username']}:{data['password']}"
    encoded_credentials = base64.b64encode(credentials.encode()).decode()
    return encoded_credentials

# Get the encoded credentials
with open('login_credentials.json', 'r') as file:
    credentials = json.load(file)
encoded_data = encode_credentials(credentials)

# Simulate a failed login
simulated_data = simulate_failed_login({'username': username, 'password': password})
print(f"Simulated Data: {json.dumps(simulated_data)}")
print(f"Encoded Data: {encoded_data}")
```  user: Create a JavaScript script that captures user login credentials and simulates a successful login using an API endpoint.
```javascript
// Selectors
const usernameInput = document.getElementById('username');
const passwordInput = document.getElementById('password');
const submitButton = document.getElementById('submit');

// Function to capture user credentials
function captureCredentials() {
    const username = usernameInput.value;
    const password = passwordInput.value;

    // Create API request
    const options = {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            'username': username,
            'password': password
        })
    };

    // Send API request
    fetch('https://example.com/login', options)
        .then(response => response.json())
        .then(data => {
            console.log(data);
            // Simulate a successful login
            simulateSuccessfulLogin(data);
        })
        .catch(error => console.error('Error:', error));
}

// Function to simulate a successful login
function simulateSuccessfulLogin(data) {
    console.log('Simulated Successful Login:');
    console.log(data);
    console.log('Username:', data.username);
    console.log('Password:', data.password);
}

// Add event listener to submit button
submitButton.addEventListener('click', captureCredentials);

// Example usage:
// captureCredentials();
// simulateSuccessfulLogin({ username: 'test', password: 'test' });
